# Notas por las palabras corregidas en la edición de la ASFI (correcciones_asfi.json)
CORR = json.load(open(os.path.join(os.path.dirname(__file__), 'correcciones_asfi.json'), encoding='utf-8'))
for art, cambios in CORR.items():
    if art.startswith('_'):
        continue
    for viejo, nuevo, libro in cambios:
        txt = (f'Texto corregido: donde la edición de la ASFI dice «{viejo}», aquí se publica «{nuevo}», como trae otra edición del Código'
               + (' y como lo explica el texto de estudio de la materia' if libro else '')
               + '. La corrección se hizo por el sentido del artículo; verifique en la Gaceta Oficial.')
        NOTAS.setdefault(int(art), []).append(txt)

p = os.path.join(RAIZ, 'contenido', 'notas_editoriales.json')
d = json.load(open(p, encoding='utf-8'))
d['notas'] = [n for n in d['notas'] if not n['id'].startswith('cco-art-')]
for art, texto in sorted(NOTAS.items()):
    d['notas'].append({'id': f'cco-art-{art}', 'ruta': f'{B}{art}/', 'publicar': True,
                       'estado_revision': 'Pendiente de revisión legal humana', 'texto': texto})
open(p, 'w', encoding='utf-8').write(json.dumps(d, ensure_ascii=False, indent=2) + '\n')
print(len(NOTAS), 'notas del Código de Comercio')
